import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Create local cleanup tracking array
  const activeTimelines = [];

  // Colors from specification
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE / BACKGROUND BACKDROP ---
  // A dark atmospheric plane to avoid flat void, dimensions fitting [-3.5, 3.5] range
  const backdropGeom = new PlaneGeometry(7.2, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();

  // Custom dark-gradient node setup
  const uInk = color(new Color(colors.ink));
  const uSurface = color(new Color(colors.surface));
  backdropMat.colorNode = vec4(uSurface, 1.0);

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -0.4);
  group.add(backdropMesh);

  // --- HERO CARD CONTAINER ---
  const cardGroup = new Group();
  // Absolute reference offset relative to node origin to center visual flow
  cardGroup.position.set(0, 0, 0);
  group.add(cardGroup);

  // Card Dimensions (designed around the 512x320 source aspect ratio, ~1.6)
  const cardWidth = 3.6;
  const cardHeight = 2.25;

  // --- COMPONENT 1: CARD FRAME BACKPLATE / ACCENT EDGE ---
  const frameGeom = new PlaneGeometry(cardWidth + 0.1, cardHeight + 0.1);
  const frameMat = new MeshBasicNodeMaterial();
  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);

  frameMat.colorNode = color(paperColor); // Default subtle border
  const frameMesh = new Mesh(frameGeom, frameMat);
  frameMesh.position.set(0, 0, -0.02);
  cardGroup.add(frameMesh);

  // --- COMPONENT 2: INTERACTIVE IMAGE PLANE ---
  const imageGeom = new PlaneGeometry(cardWidth, cardHeight);
  const imageMat = new MeshBasicNodeMaterial();
  imageMat.colorNode = color(new Color(colors.surface)); // Fallback till texture loads

  const imageMesh = new Mesh(imageGeom, imageMat);
  imageMesh.position.set(0, 0, 0);
  cardGroup.add(imageMesh);

  // Texture loading
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMat.colorNode = void 0; // Reset fallback
      imageMat.map = texture;
      imageMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('PrismNode texture load error:', err);
    });
  }

  // --- COMPONENT 3: CAPTION STRIP & METADATA TEXT ---
  // Subhead and mono caption markers
  const titleText = ctx.fontAtlas.createText('JOURNAL DE L\'ATELIER', {
    fontSize: 0.12,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-cardWidth / 2 + 0.15, -cardHeight / 2 - 0.28, 0.01);
  cardGroup.add(titleText);

  const numText = ctx.fontAtlas.createText('N°01', {
    fontSize: 0.08,
    color: colors.accent,
    align: 'right'
  });
  numText.position.set(cardWidth / 2 - 0.15, -cardHeight / 2 - 0.25, 0.01);
  cardGroup.add(numText);

  // --- BEHAVIORS & INTERACTION ---
  const interactionState = {
    hovered: false,
    pressed: false
  };

  // Hover: rise-in subtle lift animation
  const onPointerOver = () => {
    interactionState.hovered = true;

    // Highlight border / accent edge on focus
    gsap.killTweensOf(frameMat);
    gsap.to(frameMat, {
      duration: 0.25,
      onUpdate: () => {
        frameMat.colorNode = color(accentColor);
      }
    });

    gsap.killTweensOf(cardGroup.position);
    const tl = gsap.to(cardGroup.position, {
      y: 0.15,
      z: 0.1,
      duration: 0.35,
      ease: 'power2.out'
    });
    activeTimelines.push(tl);
  };

  const onPointerOut = () => {
    interactionState.hovered = false;
    interactionState.pressed = false;

    gsap.killTweensOf(frameMat);
    gsap.to(frameMat, {
      duration: 0.35,
      onUpdate: () => {
        frameMat.colorNode = color(paperColor);
      }
    });

    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.scale);

    const tlPos = gsap.to(cardGroup.position, {
      y: 0,
      z: 0,
      duration: 0.45,
      ease: 'power3.out'
    });
    const tlScale = gsap.to(cardGroup.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.3,
      ease: 'power2.out'
    });
    activeTimelines.push(tlPos, tlScale);
  };

  // Click: press-down animation & emit event
  const onPointerDown = () => {
    interactionState.pressed = true;

    gsap.killTweensOf(cardGroup.scale);
    const tl = gsap.to(cardGroup.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.12,
      ease: 'power1.out'
    });
    activeTimelines.push(tl);

    // Emit event from navigation map
    ctx.emit('hub-journal.select', {
      nodeId: config.id,
      capability: 'capability:notion.cms'
    });
  };

  const onPointerUp = () => {
    if (interactionState.pressed) {
      interactionState.pressed = false;
      gsap.killTweensOf(cardGroup.scale);
      const tl = gsap.to(cardGroup.scale, {
        x: interactionState.hovered ? 1.01 : 1.0,
        y: interactionState.hovered ? 1.01 : 1.0,
        z: interactionState.hovered ? 1.01 : 1.0,
        duration: 0.25,
        ease: 'back.out(1.7)'
      });
      activeTimelines.push(tl);
    }
  };

  // Bind to system routing via userData handlers
  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  // Cleanup block
  group.userData.cleanup = () => {
    activeTimelines.forEach(tl => tl.kill());
    backdropGeom.dispose();
    backdropMat.dispose();
    frameGeom.dispose();
    frameMat.dispose();
    imageGeom.dispose();
    imageMat.dispose();
  };

  return group;
}
